// launch-factory: 후기·상품 문의 조립. 순서: 요청 제한(DB) → 멱등 키 → 입력 검사 → Turnstile → 저장. 읽기는 게시된 글만 나간다.
// 후기는 로그인한 사람만 쓰고(한 사람이 한 대상에 한 번), 질문은 로그인 없이도 쓴다. 대상(subjectType·subjectId)은 제품이 정한다(예: product / 상품 id).
// 게시 방식: 기본은 바로 게시하고 나중에 검토(after). REVIEWS_MODERATION=before 면 검토를 마친 뒤에 게시한다.
import { hitRateLimit, user } from "@launch-factory/db"
import { actorFromUser } from "@launch-factory/inquiry"
import { createReviewsService, type ReviewsActor, type ReviewsService, type SubmitContext } from "@launch-factory/reviews"
import { createRateLimiter, ipAddressFromEnv, warnNoIpOnce } from "@launch-factory/security/rate-limit"
import { createTurnstile } from "@launch-factory/security/turnstile"
import { eq } from "drizzle-orm"
import { authPort } from "@/lib/launch/auth"
import { database } from "@/lib/launch/db"
import { env, optional, required } from "@/lib/launch/env"

let cached: Promise<ReviewsService> | undefined

export function reviews(): Promise<ReviewsService> {
  return (cached ??= build())
}

/** 게시 방식. 모르는 값은 켤 때 멈춘다(켜진 척하며 검토 없이 게시하는 것이 가장 나쁘다) */
function moderation(): "after" | "before" {
  const v = optional("REVIEWS_MODERATION") ?? "after"
  if (v !== "after" && v !== "before") throw new Error('REVIEWS_MODERATION must be "after" or "before"')
  return v
}

async function build(): Promise<ReviewsService> {
  const db = await database()
  const live = env().LF_MODE === "live"
  return createReviewsService({
    db,
    // 믿을 IP 머리는 환경이 정한다(대장 D205). 인증·보안·문의 항목과 같은 함수라 같은 사람을 같은 IP 로 센다
    limiter: createRateLimiter({ store: { hit: (key, windowMs, now) => hitRateLimit(db, key, windowMs, now) }, ipAddress: ipAddressFromEnv(process.env), onNoIp: warnNoIpOnce() }),
    turnstile: createTurnstile(live ? { mode: "live", secretKey: required("TURNSTILE_SECRET_KEY") } : { mode: "mock" }),
    moderation: moderation(),
  })
}

/** 지금 요청의 로그인 사용자(제출 맥락). 대리 로그인 세션은 로그인하지 않은 것으로 본다 — 관리자가 사용자 이름으로 글을 쓰지 못한다 */
export async function submitContext(): Promise<Pick<SubmitContext, "userId" | "displayName">> {
  const s = await (await authPort()).session()
  if (!s.ok || !s.data || s.data.impersonatedBy) return {}
  return { userId: s.data.userId, ...(s.data.name ? { displayName: s.data.name } : {}) }
}

/**
 * 지금 로그인한 사람의 행위자(답변·숨김·관리 목록). 로그아웃·정지·대리 세션 → null.
 * 소유자 = 확인된 이메일이 INQUIRY_OWNER_EMAIL 과 같은 사람, 관리자 = user.role 에 admin(Better Auth admin 플러그인과 같은 규칙).
 * 입력의 isOwner·role·userId 는 읽지 않는다 — 세션의 사용자 행으로만 정한다.
 */
export async function reviewsActor(): Promise<ReviewsActor | null> {
  const s = await (await authPort()).session()
  if (!s.ok || !s.data || s.data.impersonatedBy) return null
  const [row] = await (await database()).select({ id: user.id, role: user.role, email: user.email, emailVerified: user.emailVerified, banned: user.banned }).from(user).where(eq(user.id, s.data.userId)).limit(1)
  return row ? actorFromUser(row, optional("INQUIRY_OWNER_EMAIL") ?? "") : null
}

// launch-factory: 후기·상품 문의 경로.
//   GET  /api/reviews?subjectType=&subjectId=&kind=review|question&sort=latest|rating-desc|rating-asc&rating=&page=&pageSize= — 공개 읽기(게시된 글만, 캐시 가능)
//   POST /api/reviews (FormData 또는 JSON) — 제출. 429 + Retry-After · 봇 400 · 칸 오류 400 · 로그인 필요 401 · 중복·처리 중 409 · 확인 불가 503.
//     폼에 숨은 입력 둘을 더한다: Turnstile 토큰 `cf-turnstile-response`, 폼을 열 때 만든 `idempotencyKey`.
import { reviews, submitContext } from "@/lib/launch/reviews"

export const runtime = "nodejs"

export async function GET(request: Request) {
  return (await reviews()).listHandler(request)
}

export async function POST(request: Request) {
  return (await reviews()).handler(request, await submitContext())
}

// launch-factory: 관리 화면 구획 — 후기·상품 문의 검토(계획 3d). 목록(게시됨·검토 대기·숨김) → 상세 → 판매자 답변 저장 → 승인·숨김·되살리기.
// 들어오는 사람: 문의 소유자(확인된 이메일이 INQUIRY_OWNER_EMAIL) 또는 관리자 — 예전 서버 액션(reviews-admin.ts)과 같은 규칙이다. 구획은 서버 액션이 아니라 후기 서비스를 직접 부른다(콘솔이 준 actor 를 그대로 넘긴다).
// 판매자는 후기를 지울 수 없다 — 지우는 행동이 없다. 숨김은 사유가 필수라 서비스에 고정 사유를 싣고(관리 화면의 행동 단추는 입력을 못 싣는다), 누가 언제 숨겼는지는 admin_actions 에 남는다.
import { defineSection, refuse } from "@launch-factory/admin-console"
import { REVIEW_STATUSES, type ModerationItem } from "@launch-factory/reviews"
import { optional } from "@/lib/launch/env"
import { reviews } from "@/lib/launch/reviews"

const MAX_ROWS = 50 // 서비스의 한 쪽 상한
const CODES: Record<string, string> = { forbidden: "forbidden", not_found: "not_found", invalid_input: "invalid_input", reason_required: "invalid_input" }
const fail = (error: string) => refuse(CODES[error] ?? "action_failed")
const HIDE_REASON = "Hidden in the admin console"
const excerpt = (r: ModerationItem) => {
  const text = (r.title?.trim() || r.body).replace(/\s+/g, " ")
  return text.length > 60 ? `${text.slice(0, 60)}…` : text
}

export const reviewsSection = defineSection({
  id: "reviews",
  part: "reviews",
  label: "Reviews",
  audience: { owner: () => optional("INQUIRY_OWNER_EMAIL") },
  statuses: REVIEW_STATUSES,
  serverSearch: true, // 서버 검색: 제목·본문·작성자 이름 부분 일치(listForModeration). 표에는 제목 일부만 보여서 화면이 다시 거르면 본문에서 찾은 글이 사라진다
  pageSize: MAX_ROWS, // 서비스의 한 쪽 상한과 같게 — 쪽 이동이 줄을 빠뜨리지 않는다
  columns: [
    { id: "excerpt", label: "Review", kind: "text", primary: true },
    { id: "kind", label: "Kind", kind: "text", secondary: true },
    { id: "rating", label: "Rating", kind: "numeric", secondary: true },
    { id: "status", label: "Status", kind: "status", filter: true },
    { id: "author", label: "Author", kind: "text", secondary: true },
    { id: "subject", label: "About", kind: "text", secondary: true },
    { id: "createdAt", label: "Posted", kind: "date" },
  ],
  list: async (actor, q) => {
    // 서비스는 쪽 번호로 읽는다 — 콘솔이 쪽 크기(pageSize 선언 = MAX_ROWS)로 offset 을 만들었으므로 나누어 떨어진다
    const size = Math.min(q.limit, MAX_ROWS)
    const r = await (await reviews()).listForModeration(actor, { ...(q.status ? { status: q.status } : {}), ...(q.search ? { search: q.search } : {}), page: Math.floor(q.offset / size) + 1, pageSize: size })
    return r.ok ? { items: r.data.items, total: r.data.total } : fail(r.error)
  },
  key: (row: ModerationItem) => row.id,
  cells: (row) => ({ excerpt: excerpt(row), kind: row.kind, rating: row.rating, status: row.status, author: row.author, subject: `${row.subjectType}/${row.subjectId}`, createdAt: row.createdAt }),
  load: async (actor, id) => {
    const r = await (await reviews()).moderationItem(actor, id)
    if (r.ok) return r.data
    return r.error === "not_found" ? null : fail(r.error)
  },
  view: (rec) => ({
    title: `${rec.kind === "review" ? "Review" : "Question"} by ${rec.author}`,
    summary: [
      { label: "Status", value: rec.status, kind: "status" },
      { label: "Kind", value: rec.kind },
      ...(rec.rating !== null ? [{ label: "Rating", value: String(rec.rating), kind: "numeric" as const }] : []),
      { label: "About", value: `${rec.subjectType}/${rec.subjectId}` },
      { label: "Verified purchase", value: rec.verified ? "yes" : "no" },
      { label: "Posted", value: rec.createdAt },
      ...(rec.title ? [{ label: "Title", value: rec.title }] : []),
      { label: "Text", value: rec.body },
      ...(rec.hiddenReason ? [{ label: "Hidden because", value: rec.hiddenReason }] : []),
    ],
  }),
  form: {
    fields: (rec) => [{ name: "answer", label: "Seller reply (shown with the post)", type: "textarea", required: true, value: rec.answerBody ?? "" }],
    save: async (actor, rec, values) => {
      const r = await (await reviews()).answer(actor, { id: rec.id, body: values.answer ?? "" })
      if (r.ok) return { message: "Reply saved." }
      return r.error === "invalid_input" ? refuse("invalid_input", { fieldErrors: { answer: ["Write a reply of up to 2000 characters."] } }) : fail(r.error)
    },
  },
  actions: {
    approve: {
      label: "Approve",
      when: (rec) => rec.status === "pending",
      run: async (actor, rec) => {
        const r = await (await reviews()).setStatus(actor, { id: rec.id, status: "published" })
        return r.ok ? { message: "Approved and published." } : fail(r.error)
      },
    },
    unhide: {
      label: "Show again",
      when: (rec) => rec.status === "hidden",
      run: async (actor, rec) => {
        const r = await (await reviews()).setStatus(actor, { id: rec.id, status: "published" })
        return r.ok ? { message: "Published again." } : fail(r.error)
      },
    },
    hide: {
      label: "Hide",
      danger: true,
      when: (rec) => rec.status !== "hidden",
      run: async (actor, rec) => {
        const r = await (await reviews()).setStatus(actor, { id: rec.id, status: "hidden", reason: HIDE_REASON })
        return r.ok ? { message: "Hidden from the public page." } : fail(r.error)
      },
    },
  },
  overview: async (actor) => {
    const r = await (await reviews()).listForModeration(actor, { status: "pending", pageSize: 1 })
    return r.ok && r.data.total > 0 ? { todo: [{ id: "pending", severity: "warning", title: "Reviews waiting for approval", count: r.data.total, status: "pending" }] } : {}
  },
})

export default reviewsSection

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

/**
 * mock 의 메모리 DB 는 프로세스 하나에 하나다. 서버 번들은 쪽·서버 액션·경로 처리기(app/api)로 갈라져 같은 모듈이 번들마다 따로 불리므로(Next/Turbopack),
 * 모듈 변수에만 두면 번들 수만큼 DB 가 생겨 경로 처리기(웹훅·크론·/api/auth)와 쪽이 서로 다른 데이터를 보았다(관리 화면 시험 실측: 경로로 만든 세션이 쪽에서 안 보였다).
 * 그래서 globalThis 에 둔다. live 는 연결 문자열이 같은 DB 를 가리키므로 모듈 변수로 충분하다.
 */
const mockStore = globalThis as { __lfMockDb?: Promise<Database> }

export function database(): Promise<Database> {
  if (env().LF_MODE === "mock") return (mockStore.__lfMockDb ??= db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }))
  return (cached ??= Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: 마이그레이션 적용. 사용법: DATABASE_URL=<직접 연결(5432)> node db/migrate.mjs
// 이 폴더의 migrations/ 를 순서대로 적용한다. 이미 적용한 파일은 건너뛴다(drizzle 기록 표).
import { fileURLToPath } from "node:url"
import postgres from "postgres"
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL is not set")
  process.exit(1)
}
if (new URL(url).port === "6543") {
  console.error("Use the direct connection (port 5432) for migrations, not the transaction pooler (6543).")
  process.exit(1)
}

const client = postgres(url, { max: 1 })
try {
  await migrate(drizzle(client), { migrationsFolder: fileURLToPath(new URL("./migrations", import.meta.url)) })
  console.log("migrations applied")
} finally {
  await client.end()
}

// 후기·상품 문의(계획 3c Task 1). 대상(subject)은 제품이 정하는 문자열 둘(subjectType·subjectId)이라 이 표는 상품 표를 모른다.
// - 후기(review)는 별점이 있고 한 사람이 한 대상에 한 번만 쓴다(부분 유일 색인). 질문(question)은 로그인 없이도 쓸 수 있고 별점이 없다.
// - 작성자 이름은 저장하기 전에 가려서(@launch-factory/reviews mask) 넣는다. 원래 이름·연락처는 저장하지 않는다.
// - 숨김은 지우지 않는다(hidden + 사유). 판매자가 후기를 지울 수 없다 — 지우는 함수가 없다.
// - 탈퇴하면 user_id 만 끊고(set null) 서비스가 작성자 이름을 「탈퇴한 사용자」로 바꾼다. 글 자체는 공개 콘텐츠라 남는다.
// 시각은 앱이 넣는다(DB 기본값 now() 에 기대지 않는다 — Task 4 D26 규칙).
import { sql } from "drizzle-orm"
import { boolean, check, index, integer, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core"
import { user } from "./auth-base.ts"

const tz = { withTimezone: true } as const

export const REVIEW_KINDS = ["review", "question"] as const
export type ReviewKind = (typeof REVIEW_KINDS)[number]
export const REVIEW_STATUSES = ["published", "pending", "hidden"] as const
export type ReviewStatus = (typeof REVIEW_STATUSES)[number]

export const reviews = pgTable(
  "reviews",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    kind: text("kind").$type<ReviewKind>().notNull(),
    subjectType: text("subject_type").notNull(),
    subjectId: text("subject_id").notNull(),
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    /** 가린 이름(예: 김**, Dana K.) */
    authorName: text("author_name").notNull(),
    /** 1~5, 후기에만 */
    rating: integer("rating"),
    title: text("title"),
    body: text("body").notNull(),
    locale: text("locale").notNull(),
    status: text("status").$type<ReviewStatus>().notNull(),
    /** 실제로 산 사람의 후기인가. 구매 기록과 잇는 일(3a)이 채운다 */
    verified: boolean("verified").notNull().default(false),
    answerBody: text("answer_body"),
    answeredAt: timestamp("answered_at", tz),
    /** 답변한 관리자·소유자 user id(공개하지 않는다) */
    answeredBy: text("answered_by"),
    hiddenReason: text("hidden_reason"),
    createdAt: timestamp("created_at", tz).notNull(),
    updatedAt: timestamp("updated_at", tz).notNull(),
  },
  (t) => [
    index("reviews_subject_idx").on(t.subjectType, t.subjectId, t.status, t.createdAt),
    index("reviews_user_idx").on(t.userId),
    uniqueIndex("reviews_one_per_user_subject_idx").on(t.userId, t.subjectType, t.subjectId).where(sql`${t.kind} = 'review' and ${t.userId} is not null`),
    check("reviews_kind_ck", sql`${t.kind} in ('review', 'question')`),
    check("reviews_status_ck", sql`${t.status} in ('published', 'pending', 'hidden')`),
    check("reviews_rating_ck", sql`(${t.kind} = 'review' and ${t.rating} between 1 and 5) or (${t.kind} = 'question' and ${t.rating} is null)`),
  ],
).enableRLS() // 공개 표는 RLS 를 명시로 켠다(정책은 만들지 않는다 — 0010_explicit_rls)

-- 접속기록 위·변조 방지(「개인정보의 안전성 확보조치 기준」 제8조제3항). access_logs는 추가 전용이다.
--   UPDATE·TRUNCATE: 항상 거부
--   DELETE: 접속일시가 1년(제8조제1항 최소 보관 기간)을 넘은 행만 허용 — 파기 작업이 2년 설정이면 그보다 늦게 지운다
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것까지는 막지 못한다 — 해시 사슬은 다음 단계, docs/qa/task-3-report.md).
CREATE FUNCTION "access_logs_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'TRUNCATE') THEN
    RAISE EXCEPTION 'access_logs is append-only: % refused', TG_OP;
  END IF;
  IF OLD.occurred_at > now() - interval '1 year' THEN
